.programmesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2435;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae5db 100%);
    border-radius: 18px;
}

.programmesim-container * {
    box-sizing: border-box;
}

.programmesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203a 0%, #1d3252 55%, #2c4a6e 100%);
    color: #f5f1e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 58, 0.32);
    border-bottom: 4px solid #c39a3e;
}

.programmesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.programmesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ecd9a6;
    background: rgba(195, 154, 62, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.programmesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3ddd0;
}

.programmesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e5c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.programmesim-period-counter #currentDay,
.programmesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203a;
}

.programmesim-round-name {
    background: #e3d6b3;
    color: #5a4413;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.programmesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a3415;
    background: #f6e3d8;
    padding: 4px 12px;
    border-radius: 999px;
}

.programmesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.programmesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
    border-top: 4px solid #2c4a6e;
}

.programmesim-card-fit { border-top-color: #1d6f6a; }
.programmesim-card-margin { border-top-color: #c39a3e; }
.programmesim-card-launch { border-top-color: #2c4a6e; }
.programmesim-card-win { border-top-color: #7a4ea3; }

.programmesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7283;
}

.programmesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203a;
}

.programmesim-card-fit .programmesim-value { color: #1d6f6a; }
.programmesim-card-margin .programmesim-value { color: #b4862b; }
.programmesim-card-launch .programmesim-value { color: #2c4a6e; }
.programmesim-card-win .programmesim-value { color: #7a4ea3; }

.programmesim-sublabel {
    font-size: 0.76rem;
    color: #7e8595;
    line-height: 1.35;
}

.programmesim-margin-fail .programmesim-value { color: #c0392b; }
.programmesim-margin-target .programmesim-value { color: #1d6f6a; }

.programmesim-budget-over { border-top-color: #c0392b; }
.programmesim-budget-over .programmesim-value { color: #c0392b; }

.programmesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203a;
    color: #f3ecdd;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.programmesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.programmesim-budget-bar.programmesim-overbudget {
    background: #5e1f17;
}

.programmesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c39a3e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.05);
}

.programmesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.programmesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203a;
    margin-bottom: 6px;
}

.programmesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34405a;
}

.programmesim-briefing-text strong { color: #1d6f6a; }
.programmesim-briefing-text em { color: #8a3415; font-style: italic; }

.programmesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
}

.programmesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203a;
    border-bottom: 2px solid #ece6d8;
    padding-bottom: 8px;
}

.programmesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283751;
    margin: 14px 0 6px;
}

.programmesim-container select,
.programmesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbc2ab;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7f0;
    color: #1c2435;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.programmesim-container select:focus,
.programmesim-container input[type="number"]:focus {
    outline: none;
    border-color: #c39a3e;
    box-shadow: 0 0 0 3px rgba(195, 154, 62, 0.18);
}

.programmesim-container select option {
    background-color: #ffffff;
    color: #1c2435;
}

.programmesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c39a3e;
}

.programmesim-range-readout,
.programmesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c4a6e;
    margin-top: 4px;
}

.programmesim-range-readout span:nth-child(2),
.programmesim-alloc-readout span:nth-child(2) {
    color: #1d6f6a;
    font-weight: 800;
}

.programmesim-hint {
    font-size: 0.8rem;
    color: #7e8595;
    margin-top: 4px;
    line-height: 1.4;
}

.programmesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.programmesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f2e8;
    border: 1px solid #e4dcc8;
    border-radius: 9px;
    padding: 8px 12px;
}

.programmesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #283751;
}

.programmesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.programmesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.programmesim-container .btn-primary {
    background: linear-gradient(135deg, #11203a 0%, #2c4a6e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f5f1e8;
    box-shadow: 0 6px 16px rgba(17, 32, 58, 0.28);
}

.programmesim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.programmesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbc2ab;
    color: #6b7283;
}

.programmesim-coach {
    background: linear-gradient(135deg, #11203a 0%, #20344f 100%);
    color: #eef0f4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 58, 0.24);
    border-left: 5px solid #c39a3e;
}

.programmesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ecd9a6;
    margin-bottom: 8px;
}

.programmesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.programmesim-coach-body strong { color: #f0d68a; }
.programmesim-coach-body em { color: #f0b79d; font-style: italic; }

.programmesim-history,
.programmesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2dccd;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.06);
}

.programmesim-history h3,
.programmesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203a;
}

.programmesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283751;
}

.programmesim-container table#usfHistoryTable th {
    background: #f1ecdf;
    color: #11203a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4dcc8;
}

.programmesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebe0;
}

.programmesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.programmesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .programmesim-container {
        padding: 14px;
    }
    .programmesim-header h1 {
        font-size: 1.7rem;
    }
    .programmesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .programmesim-value {
        font-size: 2rem;
    }
    .programmesim-clock {
        margin-left: 0;
    }
    .programmesim-period-counter {
        font-size: 0.88rem;
    }
    .programmesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .programmesim-alloc-row {
        flex-wrap: wrap;
    }
    .programmesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .programmesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, self-contained) ===== */
.programmesim-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2a1f36; text-align: center; padding: 4px 2px 8px; }
.programmesim-cm-title { font-size: 20px; font-weight: 700; color: #4a2f6e; margin-bottom: 14px; }
.programmesim-cm-scorewrap { background: linear-gradient(135deg, #4a2f6e 0%, #7a4fb0 55%, #a884d8 100%); color: #f6f1fc; border-radius: 14px; padding: 18px 16px; margin: 0 auto 16px; max-width: 420px; }
.programmesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; }
.programmesim-cm-score-max { font-size: 20px; font-weight: 600; opacity: 0.85; }
.programmesim-cm-grade { font-size: 18px; font-weight: 700; margin-top: 8px; }
.programmesim-cm-badges { margin-top: 10px; }
.programmesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; padding: 4px 12px; border-radius: 999px; }
.programmesim-cm-badge-ok { background: #e2d5f2; color: #4a2f6e; }
.programmesim-cm-badge-miss { background: #f7e2cf; color: #9a5a16; }
.programmesim-cm-kpis { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin: 0 auto 14px; max-width: 500px; }
.programmesim-cm-kpi { flex: 1 1 105px; min-width: 105px; background: #f3eefa; border: 1px solid #e2d5f2; border-radius: 10px; padding: 10px 6px; }
.programmesim-cm-kpi-val { font-size: 20px; font-weight: 700; color: #5e3d8a; }
.programmesim-cm-kpi-lbl { font-size: 11px; font-weight: 600; color: #665a74; text-transform: uppercase; letter-spacing: .3px; margin-top: 2px; }
.programmesim-cm-insights { text-align: left; max-width: 520px; margin: 0 auto; background: #f8f5fc; border-left: 4px solid #7a4fb0; border-radius: 8px; padding: 12px 16px; }
.programmesim-cm-ins-h { font-weight: 700; color: #4a2f6e; margin-bottom: 6px; font-size: 14px; }
.programmesim-cm-insights ul { margin: 0; padding-left: 18px; }
.programmesim-cm-insights li { font-size: 13px; line-height: 1.5; margin-bottom: 6px; color: #34283f; }
@media (max-width: 480px) { .programmesim-cm-kpi { flex-basis: 40%; } .programmesim-cm-score { font-size: 38px; } .programmesim-cm-scorewrap { max-width: 100%; } }

