(function() {
    'use strict';

    class ProgrammeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Designing the Programme`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (concept 1915).
            this.RFP_VALUE = 1.80;          // £1.8m fixed budget envelope, in £M
            this.BESPOKE_COST = 2.60;       // faculty-heavy bespoke design, the gap to close
            this.MARGIN_FLOOR = 30;         // MD's minimum contribution margin %
            this.MARGIN_TARGET = 38;        // MD's 2-year target custom margin %
            this.START_MARGIN = 32;         // blended contribution margin %
            this.LAUNCH_TARGET = 70;        // launch-readiness needed for a credible 10-week cohort 1
            this.WIN_TARGET = 65;           // win probability needed to beat two rivals

            // Concept truths.
            this.TRUE_NEED = `behaviour`;
            this.TRUE_BUYER = `sponsor`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 20,
                    margin: this.START_MARGIN,
                    launch: 15,
                    win: 25,
                    designCost: this.BESPOKE_COST,    // £M, starts at the unfundable bespoke baseline
                    perLearnerDays: 0,
                    facultyOverload: false,
                    overBudget: true,
                    marginBreach: false,
                    fitHistory: [20],
                    launchHistory: [15],
                    winHistory: [25],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook play.
                state.decisions = {
                    need: `reskilling`,
                    buyer: `everyone`,
                    audience: `one`,
                    objectives: 50,
                    format: `custom`,
                    spine: 50,
                    outcome: `overbudget`,
                    inperson: 3,
                    virtual: 1.5,
                    digital: 1,
                    application: 1,
                    faculty: `everywhere`,
                    impact: `l1l2`,
                    launchplan: `promise`,
                    pitch: `features`,
                    extradays: `give`,
                    discount: `match`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const need = document.getElementById(`needInput`);
                const buyer = document.getElementById(`buyerInput`);
                const aud = document.getElementById(`audienceInput`);
                const obj = document.getElementById(`objectivesInput`);
                if (need) decisions.need = need.value;
                if (buyer) decisions.buyer = buyer.value;
                if (aud) decisions.audience = aud.value;
                if (obj) decisions.objectives = parseInt(obj.value, 10);
                if (!Number.isFinite(decisions.objectives) || decisions.objectives < 0 || decisions.objectives > 100) {
                    warn(`warn_objectives_range`); return false;
                }
            } else if (round === 2) {
                const fmt = document.getElementById(`formatInput`);
                const spine = document.getElementById(`spineInput`);
                const out = document.getElementById(`outcomeInput`);
                if (fmt) decisions.format = fmt.value;
                if (spine) decisions.spine = parseInt(spine.value, 10);
                if (out) decisions.outcome = out.value;
                if (!Number.isFinite(decisions.spine) || decisions.spine < 0 || decisions.spine > 100) {
                    warn(`warn_spine_range`); return false;
                }
            } else if (round === 3) {
                const inp = document.getElementById(`inpersonInput`);
                const vir = document.getElementById(`virtualInput`);
                const dig = document.getElementById(`digitalInput`);
                const app = document.getElementById(`applicationInput`);
                const fac = document.getElementById(`facultyInput`);
                const imp = document.getElementById(`impactInput`);
                const lp = document.getElementById(`launchplanInput`);
                if (inp) decisions.inperson = parseFloat(inp.value);
                if (vir) decisions.virtual = parseFloat(vir.value);
                if (dig) decisions.digital = parseFloat(dig.value);
                if (app) decisions.application = parseFloat(app.value);
                if (fac) decisions.faculty = fac.value;
                if (imp) decisions.impact = imp.value;
                if (lp) decisions.launchplan = lp.value;
                const modes = [decisions.inperson, decisions.virtual, decisions.digital, decisions.application];
                if (modes.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_modes_negative`); return false;
                }
                const days = Math.round((decisions.inperson + decisions.virtual + decisions.digital + decisions.application) * 10) / 10;
                if (days < 6 || days > 10) {
                    warn(`warn_days_band`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const ed = document.getElementById(`extradaysInput`);
                const di = document.getElementById(`discountInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (ed) decisions.extradays = ed.value;
                if (di) decisions.discount = di.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, launchDelta = 0, winDelta = 0;
            let marginDelta = 0;        // direct change to contribution margin %
            let costTarget = null;      // if set, designCost is driven toward this (£M)
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the learning need & the decision-economic buyer (Common Error 1).
                if (d.need === this.TRUE_NEED) {
                    fitDelta += 12; winDelta += 5; coachKey = `coach_r1_need_right`;
                } else if (d.need === `everything`) {
                    // Trying to satisfy all three balloons scope to an unfundable design.
                    fitDelta += 2; launchDelta -= 8; coachKey = `coach_r1_everything`;
                } else {
                    // Reskilling or asset alone serves one stakeholder, misses the renewal outcome.
                    fitDelta += 1; coachKey = `coach_r1_partial`;
                }

                if (d.buyer === this.TRUE_BUYER) {
                    fitDelta += 8; winDelta += 5;
                    if (d.need === this.TRUE_NEED) coachKey = `coach_r1_diag_sharp`;
                } else if (d.buyer === `everyone`) {
                    fitDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r1_everyone` : coachKey;
                } else {
                    fitDelta -= 2;
                }

                if (d.audience === `segmented`) { fitDelta += 6; }
                else if (d.audience === `one`) { fitDelta -= 4; }
                else { fitDelta -= 8; launchDelta -= 4; }

                // Outcome-linked objectives, not a topic list.
                if (d.objectives >= 70) { fitDelta += 5; winDelta += 3; }
                else if (d.objectives <= 30) { fitDelta -= 8; coachKey = `coach_r1_topics`; }

                summaryKey = (d.need === this.TRUE_NEED && d.buyer === this.TRUE_BUYER) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Open vs custom vs hybrid under the fixed envelope (Common Errors 2 & 3).
                const spine = d.spine;
                if (d.format === `hybrid`) {
                    // Hybrid closes the gap while preserving relevant fit — the central lever.
                    coachKey = `coach_r2_hybrid`;
                    // A custom spine of ~40-60% gives strong fit; too little open = no saving,
                    // too much open = collapsed fit (cheap-by-default).
                    if (spine >= 40 && spine <= 65) {
                        fitDelta += 12; winDelta += 6;
                        costTarget = 1.70;
                        coachKey = `coach_r2_hybrid_balanced`;
                    } else if (spine > 65) {
                        // Mostly custom spine: better fit but the gap barely closes.
                        fitDelta += 9;
                        costTarget = 2.20;
                    } else {
                        // Thin spine, mostly generic open: cheap but fit collapses.
                        fitDelta -= 6; winDelta -= 4;
                        costTarget = 1.45;
                        coachKey = `coach_r2_thinspine`;
                    }
                    launchDelta += 8;
                } else if (d.format === `custom`) {
                    // Bespoke-by-default: maximum fit, blows budget and timeline.
                    fitDelta += 9;
                    launchDelta -= 10;
                    costTarget = this.BESPOKE_COST;
                    coachKey = `coach_r2_custom`;
                } else {
                    // Mostly open: cheap and fast but dilutes relevance (fit drops to ~4/10).
                    fitDelta -= 14; winDelta -= 6;
                    launchDelta += 12;
                    costTarget = 1.20;
                    coachKey = `coach_r2_open`;
                }

                // Closing the gap: by format/delivery (right) vs cutting the outcome / over-budget.
                if (d.outcome === `format`) {
                    fitDelta += 5; winDelta += 5;
                } else if (d.outcome === `cutoutcome`) {
                    fitDelta -= 10; winDelta -= 5; coachKey = `coach_r2_cutoutcome`;
                } else {
                    // Bidding over budget: the MD won't approve and the client can't fund it.
                    winDelta -= 10; coachKey = `coach_r2_overbudget`;
                    if (costTarget !== null && costTarget < this.BESPOKE_COST) costTarget = Math.max(costTarget, this.RFP_VALUE + 0.30);
                }

                summaryKey = (d.format === `hybrid` && spine >= 40 && spine <= 65 && d.outcome === `format`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Configure delivery modes + faculty under the constraints (Common Error 4).
                const inperson = d.inperson, virtual = d.virtual, digital = d.digital, application = d.application;
                const days = inperson + virtual + digital + application;
                ds.perLearnerDays = Math.round(days * 10) / 10;

                // Delivery cost per learner (£k): in-person dearest, digital cheapest.
                // Cohort of 120, budget per head £15k. We move designCost toward the modelled cost.
                const perLearnerK = inperson * 2.4 + virtual * 1.1 + digital * 0.5 + application * 1.3 + 2.0;
                costTarget = Math.round((perLearnerK * 120) / 1000 * 100) / 100; // £M

                // Application/coaching drives L3/L4 impact and fit; pure in-person is dear with
                // diminishing fit; digital alone is cheap but thin.
                if (application >= 1.5) { fitDelta += 5; }
                else if (application < 0.5) { fitDelta -= 5; }
                if (digital >= 1 && virtual >= 1) { launchDelta += 6; } // scalable modes speed launch
                if (inperson <= 3) { launchDelta += 5; }                // a lean, blended mix builds faster
                if (inperson > 5) { fitDelta -= 3; launchDelta -= 6; coachKey = `coach_r3_facultyheavy`; }

                // Faculty allocation: 3 of 5 available, the other 2 protect £0.6m open revenue.
                if (d.faculty === `leverage`) {
                    fitDelta += 8; marginDelta += 4; winDelta += 5; coachKey = `coach_r3_leverage`;
                } else if (d.faculty === `everywhere`) {
                    // Over-allocation: double-books faculty, cannibalises open revenue, hits margin.
                    fitDelta += 3; marginDelta -= 7; launchDelta -= 6;
                    ds.facultyOverload = true;
                    coachKey = `coach_r3_overalloc`;
                } else {
                    // Barely any faculty: protects open revenue but the strategy spine loses credibility.
                    fitDelta -= 9; winDelta -= 5; coachKey = `coach_r3_nofaculty`;
                }

                // Impact measurement designed in (Kirkpatrick L3/L4).
                if (d.impact === `l3l4`) { fitDelta += 6; winDelta += 6; }
                else if (d.impact === `l1l2`) { fitDelta += 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_l1l2` : coachKey; }
                else { fitDelta -= 7; winDelta -= 5; coachKey = `coach_r3_noimpact`; }

                // Time-to-launch & phasing.
                if (d.launchplan === `phased`) {
                    launchDelta += 37; winDelta += 5; coachKey = (d.faculty === `leverage` && d.impact === `l3l4`) ? `coach_r3_configured` : coachKey;
                } else if (d.launchplan === `promise`) {
                    launchDelta -= 8; winDelta -= 4; coachKey = `coach_r3_promise`;
                } else {
                    // Asking to move the date: safe build but loses commercial ground.
                    launchDelta += 6; winDelta -= 8; coachKey = `coach_r3_slip`;
                }

                summaryKey = (d.faculty === `leverage` && d.impact === `l3l4` && d.launchplan === `phased`) ? `sum_r3_good` : (d.faculty === `everywhere` ? `sum_r3_overalloc` : `sum_r3_weak`);
            } else if (round === 4) {
                // Pitch, defend scope, protect margin (Common Error 5).
                if (d.pitch === `outcomes`) { fitDelta += 4; winDelta += 10; coachKey = `coach_r4_outcomes`; }
                else if (d.pitch === `features`) { winDelta += 2; coachKey = `coach_r4_features`; }
                else { winDelta -= 6; marginDelta -= 2; coachKey = `coach_r4_pricepitch`; }

                // More days at the same price (the margin trap).
                if (d.extradays === `hold`) {
                    marginDelta += 3; winDelta += 3;
                } else if (d.extradays === `trade`) {
                    marginDelta += 1; winDelta += 6; coachKey = `coach_r4_trade`;
                } else {
                    // Give two days free: 240 extra learner-days, margin collapses (31% -> 19%).
                    marginDelta -= 12; coachKey = `coach_r4_givedays`;
                }

                // Discount demand.
                if (d.discount === `floor`) {
                    marginDelta += 2; winDelta += 3;
                } else if (d.discount === `phased`) {
                    // Phased cohort-1 proof is the win-protecting move.
                    winDelta += 8; marginDelta += 1; coachKey = (d.extradays !== `give`) ? `coach_r4_phased` : coachKey;
                } else {
                    // Match the cut: wins the room but breaks the floor.
                    marginDelta -= 9; winDelta += 3; coachKey = `coach_r4_discount`;
                }

                // Conviction nudges win probability.
                winDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.pitch === `outcomes` && d.extradays !== `give` && d.discount !== `match`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cost / budget accounting: ease designCost toward the round's target if set.
            if (costTarget !== null) {
                ds.designCost = Math.round((ds.designCost + (costTarget - ds.designCost) * 0.92) * 100) / 100;
            }
            ds.overBudget = ds.designCost > this.RFP_VALUE + 0.001;

            // The cost envelope only bites once the team owns the design (Round 2 onward). In
            // Round 1 the £2.6m figure is just the inherited bespoke baseline, not their choice.
            if (round >= 2) {
                if (ds.overBudget) {
                    // Over budget caps win probability and drags margin — but recoverably.
                    const overshoot = ds.designCost - this.RFP_VALUE;      // £M over
                    marginDelta -= Math.min(6, overshoot * 8);
                    winDelta -= Math.min(12, overshoot * 14);
                } else {
                    // Headroom under the envelope protects/lifts margin toward the MD's target.
                    marginDelta += Math.min(5, (this.RFP_VALUE - ds.designCost) * 10);
                }
            }

            // Apply deltas with headroom (start low, keep registering through the final round).
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.launch = Math.max(0, Math.min(100, ds.launch + launchDelta));
            ds.win = Math.max(0, Math.min(100, ds.win + winDelta));
            ds.margin = Math.max(0, Math.min(55, Math.round((ds.margin + marginDelta) * 10) / 10));

            // marginBreach reflects the CURRENT margin (not sticky) — a recovered margin clears it.
            ds.marginBreach = ds.margin < this.MARGIN_FLOOR;

            ds.fitHistory.push(Math.round(ds.fit));
            ds.launchHistory.push(Math.round(ds.launch));
            ds.winHistory.push(Math.round(ds.win));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0: persist composite so express_resolveDomainScore (domainState.performance.overallScore) resolves.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                launch: Math.round(ds.launch),
                launchDelta: Math.round(launchDelta),
                win: Math.round(ds.win),
                winDelta: Math.round(winDelta),
                designCost: ds.designCost,
                overBudget: ds.overBudget,
                marginBreach: ds.marginBreach,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

