                if (card) {
                    card.classList.toggle(`programmesim-margin-fail`, Number(v) < this.MARGIN_FLOOR);
                    card.classList.toggle(`programmesim-margin-target`, Number(v) >= this.MARGIN_TARGET);
                }
                return (Math.round(Number(v) * 10) / 10) + `%`;
            });

            uiManager.bind(`launchDisplay`, `domainState.launch`, (v) => Math.round(v));
            uiManager.bind(`winDisplay`, `domainState.win`, (v) => Math.round(v));

            uiManager.bind(`budgetDisplay`, `domainState.designCost`, (v) => {
                const card = document.querySelector(`.programmesim-card-margin`);
                const bar = document.querySelector(`.programmesim-budget-bar`);
                if (bar) bar.classList.toggle(`programmesim-overbudget`, Number(v) > this.RFP_VALUE + 0.001);
                return `£` + Number(v).toFixed(2) + `M / £1.80M`;
            });

            const self = this;

            // Objectives slider readout.
            const obj = document.getElementById(`objectivesInput`);
            const objReadout = document.getElementById(`objectivesReadout`);
            if (obj && objReadout) {
                objReadout.textContent = obj.value;
                obj.addEventListener(`input`, function() { objReadout.textContent = obj.value; });
            }

            // Spine slider readout.
            const sp = document.getElementById(`spineInput`);
            const spReadout = document.getElementById(`spineReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }

            // Per-learner days live total.
            const dayIds = [`inpersonInput`, `virtualInput`, `digitalInput`, `applicationInput`];
            const daysReadout = document.getElementById(`daysReadout`);
            const recompute = function() {
                let total = 0;
                dayIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (daysReadout) daysReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.programmesim-alloc-readout`);
                if (bar) bar.style.color = (total < 6 || total > 10) ? `#c0392b` : ``;
            };
            dayIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

