        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fitHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                programmeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fitHistory },
