        // v1.1.0: single source of truth for the composite (verbatim v1.0.0 formula).
        _composite(ds) {
            const fit = Math.round(ds.fit);
            const margin = Math.round(ds.margin * 10) / 10;
            const launch = Math.round(ds.launch);
            const win = Math.round(ds.win);
            return Math.round(fit * 0.30 + launch * 0.25 + win * 0.25 + Math.min(100, margin / this.MARGIN_TARGET * 100) * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const margin = Math.round(ds.margin * 10) / 10;
            const launch = Math.round(ds.launch);
            const win = Math.round(ds.win);

            const marginOk = margin >= this.MARGIN_FLOOR;
            const overBudget = ds.overBudget;
            const wonBid = win >= this.WIN_TARGET && marginOk && !overBudget;
            const composite = this._composite(ds);

            let performance = `Lost the Bid`, performanceKey = `grade_lost`;
            if (wonBid && fit >= 75 && launch >= this.LAUNCH_TARGET && margin >= this.MARGIN_TARGET && composite >= 80) { performance = `Mandate Won, Margin Lifted`; performanceKey = `grade_wonlifted`; }
            else if (wonBid && fit >= 70 && launch >= this.LAUNCH_TARGET) { performance = `Mandate Won`; performanceKey = `grade_won`; }
            else if (win >= this.WIN_TARGET && !marginOk) { performance = `Won on Undeliverable Terms`; performanceKey = `grade_undeliverable`; }
            else if (win >= this.WIN_TARGET && overBudget) { performance = `Priced Out of the Envelope`; performanceKey = `grade_pricedout`; }
            else if (win > 45) { performance = `Shortlisted, Not Selected`; performanceKey = `grade_shortlisted`; }

            const insights = [];
            if (wonBid && margin >= this.MARGIN_TARGET) insights.push(window.mySimulation.t(`insight_excellent`));
            else if (wonBid) insights.push(window.mySimulation.t(`insight_won`));
            else if (win >= this.WIN_TARGET && !marginOk) insights.push(window.mySimulation.t(`insight_undeliverable`));
            else if (overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (!marginOk) insights.push(window.mySimulation.t(`insight_marginbreach`));
            if (ds.facultyOverload) insights.push(window.mySimulation.t(`insight_faculty`));
            if (launch < this.LAUNCH_TARGET) insights.push(window.mySimulation.t(`insight_launch`));
            if (fit < 50) insights.push(window.mySimulation.t(`insight_lowfit`));
            if (wonBid && margin >= this.MARGIN_TARGET && launch >= this.LAUNCH_TARGET) insights.push(window.mySimulation.t(`insight_renewal`));

            return {
                fit: fit,
                margin: margin,
                launch: launch,
                win: win,
                designCost: ds.designCost,
                wonBid: wonBid,
                met: wonBid,
                composite: composite,
                overallScore: composite,
                performance: performance,
                performanceKey: performanceKey,
                totalPeriods: history.length,
                insights: insights
            };
        }

        // v1.1.0: localized completion debrief (engine otherwise shows a generic fallback).
        formatCompletionMessage(summary) {
            const t = (k) => (window.mySimulation ? window.mySimulation.t(k) : k);
            const s = summary || {};
            const raw = (s.composite != null) ? s.composite : (s.overallScore != null ? s.overallScore : 0);
            const score = Math.max(0, Math.min(100, Math.round(Number(raw) || 0)));
            const grade = s.performanceKey ? t(s.performanceKey) : (s.performance || '');
            const badge = s.met
                ? `<span class="programmesim-cm-badge programmesim-cm-badge-ok">${t('cm_targets_met')}</span>`
                : `<span class="programmesim-cm-badge programmesim-cm-badge-miss">${t('cm_targets_missed')}</span>`;
            const kpi = (k, v, suf) => `<div class="programmesim-cm-kpi"><div class="programmesim-cm-kpi-val">${(v != null ? v : '—')}${suf || ''}</div><div class="programmesim-cm-kpi-lbl">${t(k)}</div></div>`;
            const ins = Array.isArray(s.insights) ? s.insights : [];
            const insHtml = ins.length
                ? `<div class="programmesim-cm-insights"><div class="programmesim-cm-ins-h">${t('cm_insights')}</div><ul>${ins.map((i) => `<li>${i}</li>`).join('')}</ul></div>`
                : '';
            return `
                <div class="programmesim-cm">
                    <div class="programmesim-cm-title">${t('cm_title')}</div>
                    <div class="programmesim-cm-scorewrap">
                        <div class="programmesim-cm-score">${score}<span class="programmesim-cm-score-max">/100</span></div>
                        <div class="programmesim-cm-grade">${grade}</div>
                        <div class="programmesim-cm-badges">${badge}</div>
                    </div>
                    <div class="programmesim-cm-kpis">
                        ${kpi('cm_kpi_fit', s.fit, '')}
                        ${kpi('cm_kpi_margin', s.margin, '%')}
                        ${kpi('cm_kpi_launch', s.launch, '')}
                        ${kpi('cm_kpi_win', s.win, '%')}
                    </div>
                    ${insHtml}
                </div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.marginBreach) return window.mySimulation.t(`hint_margin`);
            if (ds.overBudget && state.currentPeriod >= 2) return window.mySimulation.t(`hint_budget`);
            if (ds.fit < 35) return window.mySimulation.t(`hint_fit`);
            if (state.currentPeriod >= 3 && ds.launch < 45) return window.mySimulation.t(`hint_launch`);
            if (ds.fit >= 70 && ds.margin >= this.MARGIN_FLOOR && ds.win >= this.WIN_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

