                    r3_days_readout:        `Total per-learner days:`,
                    r3_days_band:           `(target 6–10)`,
                    r3_faculty_label:       `Where do you place the 3 available senior strategy faculty?`,
                    r3_impact_label:        `How do you design impact measurement in?`,
                    r3_launch_label:        `How do you hit the 10-week cohort-1 launch when a full build needs 16–18 weeks?`,
                    mode_inperson:          `In-person intensives — high impact, high cost, faculty-led`,
                    mode_virtual:           `Virtual-live sessions — moderate cost, scalable`,
                    mode_digital:           `Asynchronous digital modules — low cost, scalable`,
